mapper.select:
SELECT *
FROM part_location
WHERE pos_x = #{posX}
  AND pos_y = #{posY}
LIMIT 1

SELECT p1.* FROM part_location p1 INNER JOIN ( SELECT part_number, pos_x, pos_y, MIN(location_id) as min_id FROM part_location WHERE part_number IN
#{pn}
AND pos_x IS NOT NULL AND pos_y IS NOT NULL GROUP BY part_number, pos_x, pos_y ) p2 ON p1.location_id = p2.min_id ORDER BY p1.pos_x, p1.pos_y

SELECT p1.* FROM part_location p1 INNER JOIN ( SELECT part_number, pos_x, pos_y, MIN(location_id) as min_id FROM part_location WHERE pos_x IS NOT NULL AND pos_y IS NOT NULL AND (
part_number LIKE CONCAT('%', #{pn}, '%')
) GROUP BY part_number, pos_x, pos_y ) p2 ON p1.location_id = p2.min_id ORDER BY p1.pos_x, p1.pos_y
